const __aiqZhLocale=/\/intl\/zh_cn(?:\/|$)/.test(location.pathname);const __aiqZhText={"Scan":"扫描","Video Transmission":"视频传输","Professor Skye":"斯凯教授","Professor Axon":"阿克森教授","labeled brain scan":"已标注的大脑扫描图","unlabeled brain scan":"未标注的大脑扫描图","Explore the lab to understand our mission while I get us set up for the day.\n":"我来做今天的准备工作，你先探索实验室，了解我们的研究任务吧。\n","Let's Go!":"出发！","To help predict eye problems so more patients get care":"帮助预测眼部问题，让更多患者得到救治","To give medical advice so patients don’t need a doctor":"给出医疗建议，让患者不再需要医生","That’s right!":"答对了！","Not quite!":"不太对！","Welcome. Great to have you here! Take a look around the lab while I get us set up for the day.":"欢迎！很高兴你能来。我先准备一下，你可以在实验室里四处看看。","Let's get started!":"开始吧！","I’m ready":"我准备好了","Search the lab":"探索实验室","Proceed to next task":"进入下一项任务","You have enough data to proceed to the next task":"你已经收集了足够的信息，可以进入下一个任务了","Knowledge Item":"知识物品","Missing":"缺失","Let's learn":"开始学习","Next page":"下一页","Previous page":"上一页","Key concepts":"关键概念","I've been watching you work, and I think I've got the hang of it! I’ll take over checking the rest of the scans. First, can you help me check the steps so I don’t mess anything up?":"我一直在看你怎么做，感觉我也摸到门道了！剩下的扫描让我来检查。不过先帮我把步骤对一遍吧，免得我搞砸什么。","Let’s do it!":"开始吧！","Fill in the blanks":"填空","blood vessels":"血管","Continue":"继续","Well done!":"很棒！","Not quite...":"不太对……","The brain is made up of {{ 86 billion }} neurons.":"大脑由{{ 860亿 }}个神经元组成。","86 million":"8600万","86 thousand":"8.6万","The brain has billions of neurons. Researchers study them at a {{ microscopic }} scale using slices about {{ 3000x }} thinner than a human hair.":"大脑里有数十亿个神经元。研究人员在{{ 微观 }}尺度上观察它们，使用的切片比头发薄约{{ 3000倍 }}。","Hello! I'm Professor Skye, your guide to AI. Professor Axon is counting on you to help train an AI model to speed up his work.":"你好！我是你的AI向导斯凯教授。阿克森教授希望你帮助训练AI模型，加快他的研究。","How do I help?":"我该怎么帮忙？","Pizza":"披萨","Let’s get those new scans!":"去收集新的扫描图吧！","Ready!":"准备好了！","Dataset {{ number }} saved":"数据集{{ number }}已保存","Dataset {{ number }}":"数据集{{ number }}","Datasets":"数据集","Drag to scan":"拖动以扫描","Scanning in progress":"正在扫描","Ready to scan":"可以开始扫描","Save dataset":"保存数据集","Scan {{ number }}":"扫描图{{ number }}","Scanning complete":"扫描完成","Scanning":"正在扫描","Total scans":"扫描图总数","Scan and save activity in the brain.":"扫描并保存大脑的活动情况。","Lets take a closer look!":"让我们仔细看看！","REVIEW DATA QUALITY":"检查数据质量","The Image is missing":"图像缺失","incorrect formatting":"格式不正确","the image is corrupted":"图像已损坏","Remove scan":"移除扫描图","Next batch":"下一批","Hmmm... Interesting choice...":"嗯……这个选择值得再想想……","That’s not quite right. Try again.":"还不太对，再试一次。","This error was present in {{number}} scans. Updating dataset...":"有{{number}}张扫描图出现了这种错误。正在更新数据集……","Updating scans...":"正在更新扫描图……","Back":"返回","Review the quality of the brain scans.":"检查大脑扫描图的质量。","Click any scan that presents an issue. \nWatch out for the following:\nImages that are too bright or too dark;\nCorrupted images;\nAnything else that could disrupt our research.":"点击有问题的扫描图。注意图像是否太亮、太暗或已经损坏，以及其他可能影响研究的问题。","Let's go!":"开始吧！","Label the brain scans.":"标注大脑扫描图。","Look at the labeling rules to understand your task. For each scan:\nUse the right color highlighters to label the right elements on the scan.\nOnce you’ve finished labeling, click ‘Submit scan’ to continue to the next one.":"先阅读标注规则。在每张扫描图上，用正确颜色的荧光笔标出对应部分。完成后，点击“提交扫描图”，继续处理下一张。","Submit scan":"提交扫描图","Capillary":"毛细血管","Neuron":"神经元","Astrocytes":"星形胶质细胞","Model Training":"模型训练","Model Testing":"模型测试","AI generated 3D map":"AI生成的三维地图","Accuracy":"准确度","REVIEW LABELLED SCANS":"检查已标注的扫描图","Remove":"移除","field report: dusky dunes":"实地报告：暮色沙丘","badge correct":"徽章正确","Training and testing the AI model with labeled data":"用已标注的数据训练和测试 AI 模型","Testing in the community to check accuracy":"在社区里测试以检验准确度","Labeled the new scans":"给新扫描打标签","slow down":"放慢速度","Submit":"提交","Access Level: VIP All-Access\nDress Code: Ready for the press!":"通行权限：贵宾全场通行　着装要求：准备好接受采访！","Finish quest":"完成任务","Outstanding work! Your report is complete, and our AI is ready to help people everywhere. You’ve built an AI that learns, adapts, and works for everyone.":"出色的工作！你的报告写完啦，我们的 AI 也准备好帮助世界各地的人了。你搭建出的这个 AI，能学习、能适应，对每个人都管用。","The Neuron":"神经元","What are neurons? What do they do?":"什么是神经元？它们有什么作用？","What are neurons? ":"什么是神经元？ ","How do neurons communicate?":"神经元怎样交流？","Brain ":"大脑 ","What is the brain? How does it work?":"什么是大脑？它怎样工作？","What does the brain do?":"大脑有什么作用？","What is it made of? ":"大脑由什么组成？ ","Microscope":"显微镜","Through the microscope":"透过显微镜观察","What does the brain look like on a microscopic scale?":"在微观尺度下，大脑是什么样的？","How small are the samples?":"样本有多小？","What can scientists see in those images?":"科学家能在图像中看到什么？","Professor Axon's Story":"阿克森教授的故事","What has Professor Axon been working on? What's his story?":"阿克森教授一直在研究什么？他有什么故事？","What’s the professor’s story?":"教授有什么故事？","Professor Axon is a {{ neuroscientist }} who has dedicated his life to studying the brain.\nHis goal has always been to create a {{ 3D map }} of brain connections related to memory. He has worked on it for decades - and still isn’t close to finishing!":"阿克森教授是一位{{ 神经科学家 }}，毕生致力于研究大脑。他一直希望绘制与记忆有关的大脑连接的{{ 三维地图 }}。他已经研究了几十年，却仍然远未完成！","What is he doing in Polar Peaks?":"他为什么来到极地之巅？","Professor Axon moved to Polar Peaks to investigate the locals’ forgetfulness. He believes that mapping brain {{ connections }} involved in memory could help reveal what is going wrong.\nBut the work is very slow to do by hand. He needs your help to train an {{ AI model }} to speed up the research.":"阿克森教授来到极地之巅，调查居民健忘的原因。他认为，绘制与记忆有关的大脑{{ 连接 }}，可能帮助找出问题所在。可是人工处理实在太慢了，他需要你帮助训练{{ AI模型 }}，加快研究。","Brain":"大脑","Nervous system":"神经系统","Network":"网络","Neurotransmitters":"神经递质","Synapse":"突触","Neuroscientist":"神经科学家","3D map":"三维地图","Connections":"连接","AI Model":"AI模型","Label":"标注","Microscopic":"微观","previous":"上一步","next":"下一步","DRAG TO SCAN":"拖动以扫描","SCANNING IN PROGRESS":"正在扫描","SAVE DATASET":"保存数据集","Scanning...":"正在扫描…","TOTAL SCANS: 1500":"扫描图总数：1500","SCAN: ":"扫描图： ","Question":"问题","Complete":"已完成","What's this?":"这是什么？","Task":"任务","Scan 1":"扫描图 1","Token 1":"样本 1","Scan 2":"扫描图 2","Token 2":"样本 2","Scan 3":"扫描图 3","Token 3":"样本 3","No output":"暂无输出"," Continue ":" 继续 ","Review":"检查"};const __aiqT=s=>__aiqZhLocale?(__aiqZhText[s]??s):s;
